param()
Add-Type -AssemblyName System.Drawing
$root=Split-Path -Parent $PSScriptRoot; $site=Join-Path $root 'website-live'
$popup=[System.Drawing.Image]::FromFile((Join-Path $site 'compr-popup.png')); $compare=[System.Drawing.Image]::FromFile((Join-Path $site 'compr-comparison-wide.png')); $logo=[System.Drawing.Image]::FromFile((Join-Path $site 'compr-logo.png'))
$bitmap=New-Object System.Drawing.Bitmap(1280,800,[System.Drawing.Imaging.PixelFormat]::Format24bppRgb); $g=[System.Drawing.Graphics]::FromImage($bitmap); $g.SmoothingMode=[System.Drawing.Drawing2D.SmoothingMode]::HighQuality; $g.InterpolationMode=[System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic; $g.Clear([System.Drawing.Color]::FromArgb(246,246,250))
$dark=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(31,29,58)); $purple=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(101,80,246)); $muted=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(100,98,116)); $white=[System.Drawing.Brushes]::White
$g.FillRectangle($dark,0,0,1280,150); $g.DrawImage($logo,54,38,74,74); $g.DrawString('COMPR FREE BETA',(New-Object System.Drawing.Font('Arial',28,[System.Drawing.FontStyle]::Bold)),$white,150,43); $g.DrawString('Find it cheaper. Save it. Compare it.',(New-Object System.Drawing.Font('Arial',17)),$white,152,83); $g.FillRectangle($purple,1000,48,214,52); $g.DrawString('NO PAYMENT',(New-Object System.Drawing.Font('Arial',15,[System.Drawing.FontStyle]::Bold)),$white,1033,63)
$g.DrawImage($compare,[System.Drawing.Rectangle]::new(38,186,820,575),0,0,$compare.Width,$compare.Height,[System.Drawing.GraphicsUnit]::Pixel); $scale=[Math]::Min(330/$popup.Width,560/$popup.Height); $pw=[int]($popup.Width*$scale); $ph=[int]($popup.Height*$scale); $g.DrawImage($popup,910,190,$pw,$ph); $g.DrawString('Current interface preview',(New-Object System.Drawing.Font('Arial',13,[System.Drawing.FontStyle]::Bold)),$muted,930,758)
$out=Join-Path $site 'compr-beta-overview.png'; $bitmap.Save($out,[System.Drawing.Imaging.ImageFormat]::Png)
$g.Dispose(); $bitmap.Dispose(); $popup.Dispose(); $compare.Dispose(); $logo.Dispose(); $dark.Dispose(); $purple.Dispose(); $muted.Dispose(); Write-Output $out
